Lemma texit_bind : forall {A B} (t : itree A) (f : A -> itree B) mo tr,
  texit (bind t f) mo tr <->
  texit t mo tr \/ exists tr1 r mo1 tr2, tpath t mo tr1 r mo1 /\ texit (f r) mo1 tr2 /\ tr = tr1 ++ tr2.
Proof.
