Lemma leaves_unreachable_m_ebind : forall {A B} (t : itree (exc A)) (f : A -> itree (exc B)) mo,
  leaves_unreachable_m (ebind t f) mo <->
  (forall tr mo', tpath t mo tr Unr mo' -> False)
